 94 :                                      final double relativeSymmetryThreshold,
 95 :                                      final double absolutePositivityThreshold)
 96 :         throws NonSquareMatrixException,
 97 :                NotSymmetricMatrixException, NotPositiveDefiniteMatrixException {
 98 : 
 99 :         if (!matrix.isSquare()) {
100 :             throw new NonSquareMatrixException(matrix.getRowDimension(),
101 :                                                matrix.getColumnDimension());
102 :         }
103 : 
104 :         final int order = matrix.getRowDimension();
105 :         lTData   = matrix.getData();
106 :         cachedL  = null;
107 :         cachedLT = null;
108 : 
109 :         // check the matrix before transformation
110 :         for (int i = 0; i < order; ++i) {
111 : 
112 :             final double[] lI = lTData[i];
113 : 
114 :             if (lTData[i][i] < absolutePositivityThreshold) {
115 :                 throw new NotPositiveDefiniteMatrixException();
116 :             }
117 :             // check off-diagonal elements (and reset them to 0)
118 :             for (int j = i + 1; j < order; ++j) {
119 :                 final double[] lJ = lTData[j];
120 :                 final double lIJ = lI[j];
121 :                 final double lJI = lJ[i];
122 :                 final double maxDelta =
123 :                     relativeSymmetryThreshold * Math.max(Math.abs(lIJ), Math.abs(lJI));
124 :                 if (Math.abs(lIJ - lJI) > maxDelta) {
125 :                     throw new NotSymmetricMatrixException();
126 :                 }
127 :                 lJ[i] = 0;
128 :            }
129 :         }
130 : 
131 :         // transform the matrix
132 :         for (int i = 0; i < order; ++i) {
133 : 
134 :             final double[] ltI = lTData[i];
135 : 
136 :             // check diagonal element
137 : 
138 :             ltI[i] = Math.sqrt(ltI[i]);
139 :             final double inverse = 1.0 / ltI[i];
140 : 
141 :             for (int q = order - 1; q > i; --q) {
142 :                 ltI[q] *= inverse;
143 :                 final double[] ltQ = lTData[q];
144 :                 for (int p = q; p < order; ++p) {
145 :                     ltQ[p] -= ltI[q] * ltI[p];
146 :                 }
147 :             }
148 : 
149 :         }
150 : 
151 :     }"

